import{_ as a,o as r,c as t,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2019Q1 Ceph社区季度进展报告","date":"2019-03-01T00:00:00.000Z","updated":"2019-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019Q1_Ceph社区季度总结.md","filePath":"posts/2019/2019Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019Q1_Ceph社区季度总结.md"};function i(s,e,n,h,m,l){return r(),t("div",null,[...e[0]||(e[0]=[_('<h1 id="ceph-社区-2019-q1-季度进展报告" tabindex="-1">Ceph 社区 2019 Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2019-q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2019 Q1 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的讨论高度集中在以下几个反复出现的技术方向：</p><p><strong>Crimson/Seastar OSD 新架构</strong>是本季度最活跃的议题，贯穿整个季度。从 <a href="./Crimson_Seastar_OSD_Meeting_2019-01.html">Crimson_Seastar_OSD_Meeting_2019-01</a>、<a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.html">Crimson_Seastar_OSD_Meeting_2019-01-08</a>) 到 <a href="/VideoSummary/posts/2019/2019-01-29_-_-_Crimson_SeaStor_OSD_Meeting.html">2019-01-29_-_-_Crimson_SeaStor_OSD_Meeting</a>)，每周均有专项会议推进，核心目标是验证新架构对快速设备（NVMe）的性能提升假设。</p><p><strong>Orchestrator 框架统一</strong>是另一条主线，涉及 SSH、Rook、DepSea、Ansible 等多种后端的抽象接口设计，在 <a href="/VideoSummary/posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.html">2019-02-11_-_-_Ceph_Orchestration_Meeting</a>) 和 <a href="./2019-02-18_-_Ceph_Orchestration_Meeting.html">2019-02-18_-_-_Ceph_Orchestration_Meeting</a> 中持续讨论。</p><p><strong>Nautilus 版本准备</strong>作为背景贯穿多个会议，多处提及 Nautilus 作为目标版本，推动各组件的稳定化工作。</p><p><strong>性能基准与 NUMA 优化</strong>在 <a href="/VideoSummary/posts/2019/Ceph_Performance_Meeting_2019-01-03.html">Ceph_Performance_Meeting_2019-01-03</a>) 和 <a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph_Performance_meeting_2019-01-17</a>) 中重点讨论，涉及 OSD 与 NIC 的NUMA 节点亲和性。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="crimson-osd-新一代高性能-osd" tabindex="-1">Crimson OSD：新一代高性能 OSD <a class="header-anchor" href="#crimson-osd-新一代高性能-osd" aria-label="Permalink to &quot;Crimson OSD：新一代高性能 OSD&quot;">​</a></h3><p>本季度 Crimson 项目取得了多项具体进展：</p><ul><li><strong>内存存储（memstore）实现</strong>：<a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.html">Crimson_Seastar_OSD_Meeting_2019-01-08</a>) 确定使用 Seastar 框架，采用原子操作替代锁，避免线程竞争。</li><li><strong>消息传递框架重构</strong>：<a href="./2019-01-29_-_Crimson_SeaStor_OSD_Meeting.html">2019-01-29_-_Crimson_SeaStor_OSD_Meeting</a> 讨论了 Crimson 消息框架的性能测试，并与现有方案进行对比。</li><li><strong>新帧格式与加密协议</strong>：<a href="/VideoSummary/posts/2019/2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting</a>) 介绍了新的消息协议和帧格式，讨论了加密协议（Serpent）的可行性。</li><li><strong>心跳机制支持</strong>：<a href="/VideoSummary/posts/2019/2019-02-12_-_-_Crimson_SeaStor_OSD_Meeting.html">2019-02-12_-_-_Crimson_SeaStor_OSD_Meeting</a>) 报告心跳功能代码已完成，待测试。</li><li><strong>线程模型确定</strong>：<a href="/VideoSummary/posts/2019/Ceph_Performance_Meeting_2019-01-10.html">Ceph_Performance_Meeting_2019-01-10</a>) 讨论了 mstar 线程模型与SPDK 集成方案，<a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-15.html">Crimson_Seastar_OSD_Meeting_2019-01-15</a>) 讨论了单线程 OSD 到单核的绑定策略。</li></ul><h3 id="numa-节点感知优化" tabindex="-1">NUMA 节点感知优化 <a class="header-anchor" href="#numa-节点感知优化" aria-label="Permalink to &quot;NUMA 节点感知优化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2019/Ceph_Performance_Meeting_2019-01-03.html">Ceph_Performance_Meeting_2019-01-03</a>) 提出为 OSD 添加 NUMA 节点状态监控基础设施，<a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph_Performance_meeting_2019-01-17</a>) 报告 Haeju 已开发新命令，可显示每个 OSD 的存储和网络 NUMA 节点并支持固定，该命令已合并。</p><h3 id="rgw-性能改进" tabindex="-1">RGW 性能改进 <a class="header-anchor" href="#rgw-性能改进" aria-label="Permalink to &quot;RGW 性能改进&quot;">​</a></h3><p><a href="./2019-01-31_-_Ceph_Performance_meeting.html">2019-01-31_-_-_Ceph_Performance_meeting</a> 中，Adam 将 IObject 集成到 RGW 以优化性能，并建议将 RGW 特定更改拆分为独立 PR。同一会议还讨论了 memstore 的 Science Star 变体，旨在消除不必要的锁定和原子操作。</p><h3 id="bluestore-重写探索" tabindex="-1">BlueStore 重写探索 <a class="header-anchor" href="#bluestore-重写探索" aria-label="Permalink to &quot;BlueStore 重写探索&quot;">​</a></h3><p><a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph_Performance_meeting_2019-01-17</a>) 提到 Adrian 正在尝试重新编写 BlueStore 以支持更多存储设备类型。</p><h3 id="nobaa-混合云数据平台" tabindex="-1">NoBaa 混合云数据平台 <a class="header-anchor" href="#nobaa-混合云数据平台" aria-label="Permalink to &quot;NoBaa 混合云数据平台&quot;">​</a></h3><p><a href="./2019-Jan-17_-_-_Ceph_Tech_Talks_-_NoBaa_-_A_data_platform_for_distributed_hybrid_clouds.html">2019-Jan-17_-_-_Ceph_Tech_Talks-<em>NooBaa</em>-_A_data_platform_for_distributed_hybrid_clouds</a> 介绍了 NooBaa 开源数据平台，支持 S3/Lambda API，计划与 OpenShift 集成，并探索与 Ceph RGW 网关的集成路径。</p><h3 id="rbd-性能测试改进" tabindex="-1">RBD 性能测试改进 <a class="header-anchor" href="#rbd-性能测试改进" aria-label="Permalink to &quot;RBD 性能测试改进&quot;">​</a></h3><p><a href="/VideoSummary/posts/2019/2019-01-31_-_-_Ceph_Performance_meeting.html">2019-01-31_-_-_Ceph_Performance_meeting</a>) 中 Nick 正在重写 FIO CBT 基准测试，简化测试流程，<a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-22.html">Crimson_Seastar_OSD_Meeting_2019-01-22</a>) 也讨论了 RBD 的性能测试和优化。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p><strong>Orchestrator 接口设计决策</strong>：<a href="/VideoSummary/posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.html">2019-02-11_-_Ceph_Orchestration_Meeting</a>) 做出了多项关键设计决定：</p><ul><li>设备清单刷新提供刷新标志，但不在 Rook/DeepSea 中实现缓存</li><li>Cats（缓存）作为独立服务实现，而非嵌入各 orchestrator</li><li>库存过滤器标签保留在各 orchestrator 内部，不暴露到通用接口</li><li>保留 orchestrator 接口中的添加/删除主机功能</li></ul><p><strong>Crimson 线程模型确定为 1:1 映射</strong>：<a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.html">Crimson_Seastar_OSD_Meeting_2019-01-08</a>) 明确当前阶段专注于 1:1 映射模式（一个 Seastar reactor 对应一个 OSD），M:N 映射留待未来考虑，理由是更易于验证性能假设。</p><p><strong>Nautilus 版本目标确认</strong>：多个会议（<a href="./2019-Jan-09_-_Ceph_Testing_Weekly.html">2019-Jan-09_-_-_Ceph_Testing_Weekly</a>、<a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph_Performance_meeting_2019-01-17</a>)）均将 Nautilus 作为当前开发周期的目标版本，RGW 异步化等特性希望在 Nautilus 中成为默认选项。</p><p><strong>Orchestrator 代码发布策略</strong>：<a href="/VideoSummary/posts/2019/2019-02-06_-_-_Ceph_Testing_Weekly.html">2019-02-06_-_-_Ceph_Testing_Weekly</a>) 明确表示 Orchestrator 测试不足，不建议发布未经充分测试的代码，讨论了将其打包到点版本发布的可能性。</p><p><strong>文档 SEO 自动化</strong>：<a href="/VideoSummary/posts/2019/Ceph_DocuBetter_Meeting_2019-01-18.html">Ceph_DocuBetter_Meeting_2019-01-18</a>) 决定将文档生成集成到 Jenkins 作业，自动生成 <code>rel canonical</code> 标签和 <code>robots.txt</code>，解决旧版本文档被搜索引擎索引的问题。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>开发者月度会议</strong>：<a href="/VideoSummary/posts/2019/2019-01-02_-_-_Ceph_Developer_Monthly.html">2019-01-02_-_-_Ceph_Developer_Monthly</a>) 和 <a href="/VideoSummary/posts/2019/February_2019_-_-_Ceph_Developer_Monthly.html">February_2019_-_-_Ceph_Developer_Monthly</a>) 分别在 1 月和 2 月举行，讨论了 Skyhook 应用需求、外部服务（EDS）集成、NFS 管理命令行接口等跨组件议题。</p><p><strong>Tech Talks 系列</strong>：<a href="/VideoSummary/posts/2019/2019-Jan-17_-_-_Ceph_Tech_Talks_-_NooBaa_-_A_data_platform_for_distributed_hybrid_clouds.html">2019-Jan-17_-_-<em>Ceph_Tech_Talks</em>-<em>NoBaa</em>-_A_data_platform_for_distributed_hybrid_clouds</a>) 举办了 NooBaa 专题技术分享，展示了生态系统中基于 Ceph 构建的上层平台。</p><p><strong>GSoC / Outreachy 项目招募</strong>：<a href="/VideoSummary/posts/2019/2019-02-06_-_-_Ceph_Testing_Weekly.html">2019-02-06_-_-_Ceph_Testing_Weekly</a>) 讨论了 Google Summer of Code 和 Outreachy 项目，计划在网站发布更多项目机会，简化申请流程，通过小规模项目评估学生能力。</p><p><strong>测试基础设施建设</strong>：<a href="/VideoSummary/posts/2019/2019-01-20_-_-_Ceph_Testing_Weekly.html">2019-01-20_-_-_Ceph_Testing_Weekly</a>) 讨论了 Rook 与 Kubernetes/OpenShift 集成测试，<a href="/VideoSummary/posts/2019/2019-Jan-09_-_-_Ceph_Testing_Weekly.html">2019-Jan-09_-_-_Ceph_Testing_Weekly</a>) 讨论了 PR 测试流程自动化，社区内部已创建 Jenkins 作业用于测试下游 PR。</p><p><strong>OVH 云服务变化</strong>：<a href="/VideoSummary/posts/2019/2019-01-20_-_-_Ceph_Testing_Weekly.html">2019-01-20_-_-_Ceph_Testing_Weekly</a>) 提及 OVH 云服务的变化对 Ceph 集群部署测试环境产生了影响，需要适配虚拟化限制和网络配置。</p><p><strong>RGW 多站点问题发现</strong>：<a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph_Performance_meeting_2019-01-17</a>) 报告在 Minneapolis F Meetup 上发现 RGW 多站点存在分布式复制问题，数据未能正确复制，可能是静默失败，引起社区关注。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论内容，预计 2019 Q2 将重点推进以下方向：</p><p><strong>Crimson OSD 进入可测试阶段</strong>：心跳、消息传递、PG 持久化等基础功能已在本季度基本完成代码，Q2 将进入系统性测试和性能基准对比阶段，验证相对于经典 OSD 的性能提升。</p><p><strong>Nautilus 版本发布准备</strong>：多个组件（RGW 异步化、Orchestrator 稳定化、NUMA 优化）均以 Nautilus 为目标，Q2 将进入集成测试和发布候选阶段。</p><p><strong>Orchestrator 框架完善</strong>：Rook OSD 创建问题、SSH Orchestrator 依赖问题、Ansible Runner Service 集成等遗留问题将在 Q2 跟进解决，集成测试平台（基于 Behave）也将继续建设。</p><p><strong>RGW 多站点复制问题修复</strong>：本季度发现的静默失败问题需要在 Q2 进行根因分析和修复。</p><p><strong>NoBaa 与 Ceph 深度集成</strong>：NoBaa 开源后，与 Ceph RGW 的集成、容器化部署和 OpenShift 集成将是 Q2 的重要探索方向。</p><p><strong>文档自动化上线</strong>：Jenkins 文档生成流水线和 SEO 优化方案将在 Q2 完成实施，改善用户查阅文档的体验。</p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2019/2019-01-02_-_-_Ceph_Developer_Monthly.html">2019-01-02 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2019/2019-01-20_-_-_Ceph_Testing_Weekly.html">2019-01-20 :: Ceph Testing Weekly</a>)</li><li><a href="/VideoSummary/posts/2019/2019-01-29_-_-_Crimson_SeaStor_OSD_Meeting.html">2019-01-29 :: Crimson SeaStor/OSD Meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-01-31_-_-_Ceph_Performance_meeting.html">2019-01-31 :: Ceph Performance meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-02-06_-_-_Ceph_Testing_Weekly.html">2019-02-06 :: Ceph Testing Weekly</a>)</li><li><a href="/VideoSummary/posts/2019/2019-02-11_-_-_Ceph_Orchestration_Meeting.html">2019-02-11 :: Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-02-12_-_-_Crimson_SeaStor_OSD_Meeting.html">2019-02-12:: Crimson SeaStor/OSD Meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-02-18_-_-_Ceph_Orchestration_Meeting.html">2019-02-18:: Ceph Orchestration Meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-02-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.html">2019-02-19:: Crimson SeaStor/OSD Weekly Meeting</a>)</li><li><a href="/VideoSummary/posts/2019/2019-Jan-09_-_-_Ceph_Testing_Weekly.html">2019-Jan-09 :: Ceph Testing Weekly</a>)</li><li><a href="/VideoSummary/posts/2019/2019-Jan-17_-_-_Ceph_Tech_Talks_-_NooBaa_-_A_data_platform_for_distributed_hybrid_clouds.html">2019-Jan-17 :: Ceph Tech Talks - NooBaa: A data platform for distributed hybrid clouds</a>)</li><li><a href="/VideoSummary/posts/2019/Ceph_DocuBetter_Meeting_2019-01-18.html">Ceph DocuBetter Meeting 2019-01-18</a>)</li><li><a href="/VideoSummary/posts/2019/Ceph_Performance_Meeting_2019-01-03.html">Ceph Performance Meeting 2019-01-03</a>)</li><li><a href="/VideoSummary/posts/2019/Ceph_Performance_Meeting_2019-01-10.html">Ceph Performance Meeting 2019-01-10</a>)</li><li><a href="/VideoSummary/posts/2019/Ceph_Performance_meeting_2019-01-17.html">Ceph Performance meeting 2019-01-17</a>)</li><li><a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-01.html">Crimson/Seastar OSD Meeting 2019-01-01</a>)</li><li><a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.html">Crimson/Seastar OSD Meeting 2019-01-08</a>)</li><li><a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-15.html">Crimson/Seastar OSD Meeting 2019-01-15</a>)</li><li><a href="/VideoSummary/posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-22.html">Crimson Seastar/OSD Meeting 2019-01-22</a>)</li><li><a href="/VideoSummary/posts/2019/February_2019_-_-_Ceph_Developer_Monthly.html">February 2019 :: Ceph Developer Monthly</a>)</li></ul>',51)])])}const g=a(o,[["render",i]]);export{S as __pageData,g as default};
